<script setup lang="ts">
import {can} from './api';
import { computed,onMounted,ref } from 'vue';
import { api,upload,type Configuration,type CapacityDocument,type DecimalCapacityRow,type CapacitySummary } from './api';
const props=defineProps<{licensed:boolean;config:Configuration;admin:boolean;dirty:boolean}>();
const emit=defineEmits<{updated:[Configuration]}>();
const tables=ref<CapacitySummary[]>([]),error=ref(''),message=ref(''),busy=ref(false),draft=ref<CapacityDocument|null>(null),data=ref(''),checked=ref(false);
const bulk=ref<CapacitySummary|null>(null),action=ref('Associate'),selected=ref<string[]>([]),zone=ref(''),medium=ref(''),replace=ref(false),enableVolume=ref(true);
const firstRow=ref(2),heightColumn=ref(1),volumeColumn=ref(2),sheet=ref(1),importNotes=ref<string[]>([]);
const templates={Main:'capacity-main.xlsx',StaticPressure:'capacity-static-pressure.xlsx',Decimal:'capacity-decimal.xlsx'};
const exampleRows=computed(()=>draft.value?.kind==='StaticPressure'?[[0,0],[3000,.75],[6000,3]]:draft.value?.kind==='Decimal'?[[0,0],[.25,.0625],[.5,.125]]:[[0,0],[3000,750],[6000,1500]]);
const valueColumnLabel=computed(()=>draft.value?.kind==='StaticPressure'?'容积修正量':draft.value?.kind==='Decimal'?'容积增量':'容积');
const kinds={Main:'主罐容表',StaticPressure:'静压力容积修正表',Decimal:'小数表'};
const heightLabels={Millimetre:'mm',Centimetre:'cm',Metre:'m'},volumeLabels={CubicMetre:'m³',Litre:'L'};
let oldHeight='Millimetre',oldVolume='CubicMetre';
async function task(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function reload(){tables.value=await api('/api/capacity-tables')}
function open(table?:CapacityDocument){draft.value=table?JSON.parse(JSON.stringify(table)):{id:crypto.randomUUID(),revision:0,number:'',name:'',kind:'Main',heightUnit:'Millimetre',volumeUnit:'CubicMetre',referenceDensityKgM3:1000,enabled:true,notes:'',points:[],decimalRows:[]};data.value=draft.value!.kind==='Decimal'&&(draft.value!.decimalRows?.length||0)>0?draft.value!.decimalRows.map(r=>[r.startHeightMm,r.endHeightMm,r.number,r.centimetreLitres,r.millimetreLitres].join('\t')).join('\n'):draft.value!.points.map(p=>p.height+'\t'+p.volume).join('\n');oldHeight=draft.value!.heightUnit;oldVolume=draft.value!.volumeUnit;checked.value=false;error.value='';importNotes.value=[];sheet.value=1;firstRow.value=2;heightColumn.value=1;volumeColumn.value=2}
async function edit(id:string){await task(async()=>open(await api<CapacityDocument>('/api/capacity-tables/'+id)))}
function points(){const lines=data.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(lines.length<2||lines.length>100000)throw Error('请输入2～100000组数据');return lines.map((line,i)=>{const cols=line.split(/[,，\t ]+/);if(cols.length!==2||cols.some(s=>s===''))throw Error('第'+(i+1)+'行应有高度、容积两列，请勿使用千位分隔符');const [height,volume]=cols.map(Number);if(!Number.isFinite(height)||!Number.isFinite(volume))throw Error('第'+(i+1)+'行存在无效数值');return {height,volume}})}
function decimalRows():DecimalCapacityRow[]{const rows=data.value.trim().split(/\r?\n/).filter(Boolean).map((line,i)=>{const values=line.trim().split(/[,，\t ]+/).map(Number);if(values.length!==5||values.some(v=>!Number.isFinite(v)))throw Error('第'+(i+1)+'行须为五列完整数值');const [startHeightMm,endHeightMm,number,centimetreLitres,millimetreLitres]=values as [number,number,number,number,number];if(startHeightMm<0||endHeightMm<=startHeightMm||number<1||number>9||!Number.isInteger(number)||centimetreLitres<0||millimetreLitres<0)throw Error('第'+(i+1)+'行区段、序号或增量无效');return {startHeightMm,endHeightMm,number,centimetreLitres,millimetreLitres}});if(!rows.length||rows.length%9)throw Error('每区段必须有1～9共9行');return rows}
function applyData(){if(!draft.value)return;if(draft.value.kind==='Decimal'){draft.value.heightUnit='Millimetre';draft.value.volumeUnit='Litre';draft.value.points=[];draft.value.decimalRows=decimalRows()}else{draft.value.points=points();draft.value.decimalRows=[]}}
function kindChanged(){checked.value=false;data.value='';if(draft.value?.kind==='Decimal'){draft.value.heightUnit='Millimetre';draft.value.volumeUnit='Litre'}}
function preview(){error.value='';try{if(!draft.value)return;applyData();if(draft.value.kind==='Decimal'){checked.value=true;message.value='五列数据已预览，保存时后台校核完整区段。';return}for(let i=0;i<draft.value.points.length;i++){const p=draft.value.points[i];if(p.height<0||p.volume<0||i>0&&p.height<=draft.value.points[i-1].height)throw Error('高度应严格递增，不能重复或为负；容积不能为负')}checked.value=true;message.value='预览校核：'+draft.value.points.length+'组数据，请核对单位、首尾数据与来源后启用。'}catch(e){checked.value=false;error.value=e instanceof Error?e.message:String(e)}}
function convertUnits(){if(!draft.value)return;try{if(data.value.trim()){const h:Record<string,number>={Millimetre:1,Centimetre:10,Metre:1000},v:Record<string,number>={CubicMetre:1,Litre:.001};data.value=points().map(p=>(p.height*h[oldHeight]/h[draft.value!.heightUnit]).toFixed(9).replace(/\.?0+$/,'')+'\t'+(p.volume*v[oldVolume]/v[draft.value!.volumeUnit]).toFixed(9).replace(/\.?0+$/,'')).join('\n')}oldHeight=draft.value.heightUnit;oldVolume=draft.value.volumeUnit;checked.value=false}catch(e){error.value='请先修正数据后再切换单位';draft.value.heightUnit=oldHeight as CapacityDocument['heightUnit'];draft.value.volumeUnit=oldVolume as CapacityDocument['volumeUnit']}}
async function save(){await task(async()=>{if(!draft.value||!checked.value)throw Error('请先预览校核');applyData();await api('/api/capacity-tables','POST',draft.value);draft.value=null;message.value='已校核保存为新版本，旧历史不重算。';await reload()})}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await task(async()=>{const q=new URLSearchParams({kind:draft.value?.kind||'Main',sheet:String(sheet.value-1),firstRow:String(firstRow.value),heightColumn:String(heightColumn.value),volumeColumn:String(volumeColumn.value)});const result=await upload<{points:{height:number;volume:number}[];notes:string[];importedRows:number;sheetName:string;decimalRows?:DecimalCapacityRow[];kind?:CapacityDocument['kind'];heightUnit?:CapacityDocument['heightUnit'];volumeUnit?:CapacityDocument['volumeUnit'];referenceDensityKgM3?:number}>('/api/capacity-tables/import-preview?'+q,file);if(!draft.value)return;if(result.kind&&result.kind!==draft.value.kind)throw Error('文件类型为'+kinds[result.kind]+'，请先选择对应的表类型再导入');if(result.heightUnit)draft.value.heightUnit=result.heightUnit;if(result.volumeUnit)draft.value.volumeUnit=result.volumeUnit;if(result.referenceDensityKgM3!=null&&draft.value.kind==='StaticPressure')draft.value.referenceDensityKgM3=result.referenceDensityKgM3;oldHeight=draft.value.heightUnit;oldVolume=draft.value.volumeUnit;data.value=draft.value?.kind==='Decimal'?(result.decimalRows||[]).map(r=>[r.startHeightMm,r.endHeightMm,r.number,r.centimetreLitres,r.millimetreLitres].join('\t')).join('\n'):result.points.map(p=>p.height+'\t'+p.volume).join('\n');checked.value=false;importNotes.value=result.notes;message.value='已读取“'+result.sheetName+'”共'+result.importedRows+'组，请核对单位并预览校核。'});(event.target as HTMLInputElement).value=''}
function bound(t:Configuration['tanks'][number],table:CapacitySummary){return table.kind==='Main'?t.metering.mainTableId===table.id:table.kind==='StaticPressure'?t.metering.staticPressureTableId===table.id:t.metering.decimalTableId===table.id}
function openBulk(table:CapacitySummary){bulk.value=table;action.value='Associate';selected.value=[];zone.value='';medium.value='';replace.value=false;enableVolume.value=true;error.value=''}
const filtered=computed(()=>props.config.tanks.filter(t=>(!zone.value||t.zone===zone.value)&&(!medium.value||t.medium===medium.value)&&(action.value!=='Remove'||!bulk.value||bound(t,bulk.value))));
const zones=computed(()=>[...new Set(props.config.tanks.map(t=>t.zone).filter(Boolean))]);
const media=computed(()=>[...new Set(props.config.tanks.map(t=>t.medium).filter(Boolean))]);
function selectAll(){selected.value=[...new Set([...selected.value,...filtered.value.map(t=>t.id)])]}
async function associate(){await task(async()=>{if(!bulk.value||selected.value.length===0)throw Error('请选择储罐');const result=await api<Configuration>('/api/capacity-tables/'+bulk.value.id+'/associations','POST',{configurationRevision:props.config.revision,tankIds:selected.value,action:action.value,replaceExisting:replace.value,enableVolume:enableVolume.value});emit('updated',result);bulk.value=null;message.value='批量配置已保存';await reload()})}
async function toggle(table:CapacitySummary){await task(async()=>{const doc=await api<CapacityDocument>('/api/capacity-tables/'+table.id);await api('/api/capacity-tables','POST',{...doc,enabled:!doc.enabled});await reload()})}
onMounted(()=>void task(reload));
const deleteTarget=ref<CapacitySummary|null>(null),deleteConfirmed=ref(false);
async function deleteTable(){if(!deleteTarget.value||!deleteConfirmed.value||busy.value)return;busy.value=true;error.value='';try{await api('/api/capacity-tables/'+deleteTarget.value.id+'?revision='+deleteTarget.value.revision+'&confirmed=true','DELETE');deleteTarget.value=null;await reload();message.value='已从当前列表删除；历史版本和计算依据保留。'}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template>
 <div class="toolbar"><span>主表、小数表、静压力修正表分别管理，保存后建立版本。</span><button v-if="admin" class="button primary" :disabled="busy" @click="open()">新增罐容表</button></div>
 <div v-if="error" role="alert" class="notice error-message">{{error}}</div><div v-if="message" class="notice success-message">{{message}}</div>
 <div v-if="dirty" class="notice">请先保存其他配置修改，再进行批量关联。</div>
 <section class="panel"><div class="table-wrap"><table><thead><tr><th>编号 / 名称</th><th>类型</th><th>版本</th><th>单位 / 参考密度</th><th>数据行</th><th>状态</th><th>已关联储罐</th><th>操作</th></tr></thead><tbody><tr v-for="t in tables" :key="t.id"><td>{{t.number}}<small>{{t.name}}</small></td><td>{{kinds[t.kind]}}</td><td>V{{t.revision}}</td><td>{{heightLabels[t.heightUnit]}} → {{volumeLabels[t.volumeUnit]}}<small v-if="t.kind==='StaticPressure'">参考密度 {{t.referenceDensityKgM3}} kg/m³</small></td><td>{{t.pointCount}}</td><td>{{t.enabled?'已启用':'已停用'}}</td><td class="table-associations">{{t.associatedTanks.join('、')||'—'}}</td><td><div class="inline-actions"><button class="text-button" @click="edit(t.id)">{{admin?'查看 / 编辑':'查看'}}</button><button v-if="admin" class="text-button" :disabled="dirty||busy" @click="openBulk(t)">批量关联</button><a v-if="licensed&&can('DataExport')" class="text-button" :href="'/api/capacity-tables/'+t.id+'/export'" :download="t.number+'-v'+t.revision+'.xlsx'">导出</a><button v-if="admin" class="text-button" @click="toggle(t)">{{t.enabled?'停用':'启用'}}</button><button v-if="admin" class="text-button" :disabled="dirty||busy" @click="deleteTarget=t;deleteConfirmed=false;error=''">删除</button></div></td></tr><tr v-if="!tables.length"><td colspan="8" class="empty">尚未录入罐容表，请录入或导入已校核资料。</td></tr></tbody></table></div></section>
 <div v-if="draft" class="modal-backdrop"><section class="modal wide-modal" role="dialog" aria-label="编辑罐容表"><div class="modal-head"><div><h2>{{draft.revision?'编辑':'新增'}}罐容表</h2><p>录入或导入 → 预览校核 → 保存启用；批量关联在列表中操作。</p></div><button class="button" @click="draft=null">关闭</button></div><form class="modal-body" @submit.prevent="save"><p v-if="error" class="error-message">{{error}}</p><p v-if="message" class="success-message">{{message}}</p><div class="config-fields"><label class="config-field">表编号 *<input v-model="draft.number" required maxlength="80" :disabled="!admin"></label><label class="config-field">表名称 *<input v-model="draft.name" required maxlength="120" :disabled="!admin"></label><label class="config-field">表类型<select aria-label="表类型" v-model="draft.kind" :disabled="!admin" @change="kindChanged"><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></label><label class="config-field">版本<input :value="draft.revision?'当前V'+draft.revision+'，保存后新增版本':'首次保存V1'" readonly></label><label class="config-field">高度单位<select aria-label="高度单位" v-model="draft.heightUnit" :disabled="!admin||draft.kind==='Decimal'" @change="convertUnits"><option v-for="(label,key) in heightLabels" :key="key" :value="key">{{label}}</option></select></label><label class="config-field">容积单位<select aria-label="容积单位" v-model="draft.volumeUnit" :disabled="!admin||draft.kind==='Decimal'" @change="convertUnits"><option v-for="(label,key) in volumeLabels" :key="key" :value="key">{{label}}</option></select></label><label v-if="draft.kind==='StaticPressure'" class="config-field">参考密度 kg/m³<input v-model.number="draft.referenceDensityKgM3" type="number" step="any" min="0.001" max="1000000" :disabled="!admin" @input="checked=false"></label><label class="config-field">资料备注<input v-model="draft.notes" maxlength="2000" :disabled="!admin"></label></div>
 <div v-if="admin" class="notice capacity-import-box"><h3>从Excel导入</h3><div class="capacity-template-actions"><a class="button" :href="'/templates/'+templates[draft.kind]" :download="kinds[draft.kind]+'-导入模板.xlsx'">下载{{kinds[draft.kind]}}模板</a><label class="button capacity-file-button">选择填写好的Excel<input type="file" accept=".xls,.xlsx" :disabled="busy" @change="importFile"></label></div><p v-if="draft.kind==='Decimal'" class="capacity-import-help">小数表按五列模板填写：起始高度mm、结束高度mm、序号1～9、厘米累计增量L、毫米累计增量L。每区段9行，起止高度每行重复，第2行起填数据。</p><p v-else class="capacity-import-help">按模板填写：A列放高度，B列放{{valueColumnLabel}}。第1行是标题，第2行起每行一组数据，保存后选择文件即可导入。模板使用mm、m³。本系统导出文件附有资料页，导入时自动采用其中明确记录的单位和静压力参考密度；其他文件请按原始资料选择。</p><details v-if="draft.kind!=='Decimal'" class="capacity-import-example"><summary>查看填写样例</summary><table><thead><tr><th>Excel行号</th><th>A列：液位高度（mm）</th><th>B列：{{valueColumnLabel}}（m³）</th></tr></thead><tbody><tr><td>1（标题）</td><td>液位高度（mm）</td><td>{{valueColumnLabel}}（m³）</td></tr><tr v-for="(row,i) in exampleRows" :key="i"><td>{{i+2}}</td><td>{{row[0]}}</td><td>{{row[1]}}</td></tr></tbody></table><p class="help">以上为演示格式；请用本罐的校准数据替换。{{draft.kind==='StaticPressure'?'B列是参考密度下的容积增量，不是总容积。':''}}</p></details><details v-if="draft.kind!=='Decimal'"><summary>其他格式设置（已有Excel与模板不同时使用）</summary><div class="config-fields"><label class="config-field">读取第几个工作表<input v-model.number="sheet" type="number" min="1" max="100"></label><label class="config-field">数据从第几行开始<input v-model.number="firstRow" type="number" min="1" max="1000"></label><label class="config-field">高度在第几列<input v-model.number="heightColumn" type="number" min="1" max="256"></label><label class="config-field">{{valueColumnLabel}}在第几列<input v-model.number="volumeColumn" type="number" min="1" max="256"></label><p class="capacity-advanced-help">工作表1就是Excel底部从左数第一个页签；行号看左侧数字。列按A=1、B=2、C=3填写。例如标题在前两行、从A3/B3开始录入数据，填：工作表1、起始行3、高度列1、{{valueColumnLabel}}列2。设置好后重新选择文件。</p></div></details><p class="help">支持xls/xlsx，最多20MiB；导入后仍需预览校核并保存。</p></div>
 <label class="config-field wide-field">{{draft.kind==='Decimal'?'起始mm、结束mm、序号、厘米增量L、毫米增量L（每行五列）':draft.kind==='StaticPressure'?'液位高度、参考密度下的容积修正量（每行两列）':'液位高度、容积（每行两列）'}}<textarea v-model="data" rows="12" :disabled="!admin" @input="checked=false"></textarea></label><p class="help">最多100000行，使用制表符、逗号或空格分隔，不使用千位分隔符。切换单位会换算已有数值。</p><p v-for="note in importNotes" :key="note" class="help">{{note}}</p><div v-if="draft.kind==='Decimal'" class="notice">小数表仅在储罐选择“主表下节点＋小数表增量”时参与。高度用mm、增量用L；旧两列表须按新格式重新校核。</div><div class="inline-actions"><button v-if="admin" type="button" class="button" @click="preview">预览校核</button><span v-if="checked">{{draft.kind==='Decimal'?(draft.decimalRows?.length||0):draft.points.length}}组 · 首行 {{draft.points[0]?.height}} / {{draft.points[0]?.volume}} · 末行 {{draft.points.at(-1)?.height}} / {{draft.points.at(-1)?.volume}}</span><button v-if="admin" class="button primary" :disabled="busy||!checked">校核并保存</button></div></form></section></div>
 <div v-if="bulk" class="modal-backdrop"><section class="modal wide-modal" role="dialog" aria-label="批量关联罐容表"><div class="modal-head"><h2>{{bulk.number}} · 批量关联</h2><button class="button" @click="bulk=null">关闭</button></div><div class="modal-body"><p v-if="error" class="error-message">{{error}}</p><div class="config-fields"><label class="config-field">操作<select aria-label="操作" v-model="action" @change="selected=[]"><option value="Associate">关联本表</option><option value="Remove">取消本表关联</option></select></label><label class="config-field">罐区筛选<select aria-label="罐区筛选" v-model="zone"><option value="">全部</option><option v-for="z in zones" :key="z">{{z}}</option></select></label><label class="config-field">介质筛选<select aria-label="介质筛选" v-model="medium"><option value="">全部</option><option v-for="m in media" :key="m">{{m}}</option></select></label></div><div class="inline-actions"><button class="button" @click="selectAll">全选筛选结果</button><button class="button" @click="selected=[]">清空选择</button><span>已选{{selected.length}}罐</span></div><div class="bulk-tanks"><label v-for="t in filtered" :key="t.id" class="checkbox"><input v-model="selected" type="checkbox" :value="t.id">{{t.code}} · {{t.medium}} {{bound(t,bulk)?'（已关联本表）':''}}</label></div><label v-if="action==='Associate'" class="checkbox"><input v-model="replace" type="checkbox">允许替换所选罐已关联的同类其他表</label><label v-if="action==='Associate'&&bulk.kind==='Main'" class="checkbox"><input v-model="enableVolume" type="checkbox">同时启用体积计算</label><p v-if="action==='Remove'" class="help">仅取消本表的关联；取消主表时同步关闭该罐体积计算。</p><button class="button primary" :disabled="busy||!selected.length" @click="associate">保存批量配置</button></div></section></div>
<div v-if="deleteTarget" class="modal-backdrop"><section class="modal" role="dialog" aria-label="删除罐容表"><div class="modal-head"><h2>删除罐容表 {{deleteTarget.number}}</h2><button class="button" @click="deleteTarget=null">取消</button></div><div class="modal-body"><p v-if="error" class="error-message">{{error}}</p><p>删除后从当前列表移除，历史版本和历史计算依据仍保留。不会删除历史数据。</p><p v-if="deleteTarget.associatedTanks.length" class="error-message">仍关联：{{deleteTarget.associatedTanks.join('、')}}。请先取消关联。</p><label class="checkbox"><input v-model="deleteConfirmed" type="checkbox">已核对表编号，确认删除</label><button class="button primary" :disabled="!deleteConfirmed||busy||!!deleteTarget.associatedTanks.length" @click="deleteTable">确认删除</button></div></section></div></template>
